// ============================================================
// PANGI HANDOFF MANAGER — Input Validator v1.0.1
// Sistema NOVA · SAGE · ATLAS + WhatsApp
// Erick Del Piero | Marzo 2026
// ============================================================

const input = $input.first().json;
const VALID_AGENTS  = ['NOVA', 'SAGE', 'ATLAS'];
const VALID_LANGS   = ['es', 'en', 'pt'];
const VALID_REASONS = [
  'intent_detected', 'cotizar_solicitado', 'comparar_solicitado',
  'agendar_solicitado', 'sage_completo', 'user_request',
  'escalation', 'return_nova', 'other'
];

const errors = [];

// ── CAMPOS REQUERIDOS ──────────────────────────────────────
if (!input.userId    || isNaN(parseInt(input.userId)))    errors.push('userId es requerido y debe ser numérico');
if (!input.sessionId || isNaN(parseInt(input.sessionId))) errors.push('sessionId es requerido y debe ser numérico');
if (!input.fromAgent) errors.push('fromAgent es requerido');
if (!input.toAgent)   errors.push('toAgent es requerido');

// ── ENUMS ──────────────────────────────────────────────────
if (input.fromAgent && !VALID_AGENTS.includes(input.fromAgent))
  errors.push(`fromAgent inválido: "${input.fromAgent}". Válidos: ${VALID_AGENTS.join(', ')}`);
if (input.toAgent && !VALID_AGENTS.includes(input.toAgent))
  errors.push(`toAgent inválido: "${input.toAgent}". Válidos: ${VALID_AGENTS.join(', ')}`);

// ── AUTOHANDOFF — INVÁLIDO ─────────────────────────────────
if (input.fromAgent && input.toAgent && input.fromAgent === input.toAgent)
  errors.push(`fromAgent y toAgent no pueden ser iguales ("${input.fromAgent}"). Un agente no puede transferirse a sí mismo.`);

// ── SANITIZAR OPCIONALES ──────────────────────────────────
const userLanguage = VALID_LANGS.includes(input.userLanguage) ? input.userLanguage : 'es';
const reason       = VALID_REASONS.includes(input.reason)     ? input.reason       : 'other';

let contextSnapshot = {};
if (input.contextSnapshot) {
  if (typeof input.contextSnapshot === 'string') {
    try { contextSnapshot = JSON.parse(input.contextSnapshot); } catch(e) { contextSnapshot = {}; }
  } else if (typeof input.contextSnapshot === 'object') {
    contextSnapshot = input.contextSnapshot;
  }
}

if (errors.length > 0) {
  return [{ json: {
    valid: false, errors,
    errorCode: 'INVALID_HANDOFF_INPUT',
    original: input
  }}];
}

return [{ json: {
  valid:           true,
  userId:          parseInt(input.userId),
  sessionId:       parseInt(input.sessionId),
  fromAgent:       input.fromAgent,
  toAgent:         input.toAgent,
  reason,
  contextSnapshot,
  userLanguage,
  userName:        input.userName || null,
  _meta: {
    timestamp:  new Date().toISOString(),
    handoffKey: `${input.fromAgent}_to_${input.toAgent}`
  }
}}];

// ── FIX v1.0.1 ────────────────────────────────────────────
// En N8N v1, executeWorkflow pasa el item ACTUAL al sub-workflow.
// No usa inputData como string — se requiere un Code node previo
// que forme el payload exacto que 05_db_manager espera.
// ──────────────────────────────────────────────────────────
const v = $('🔍 Validar Input de Handoff').first().json;

return [{ json: {
  operation: 'logHandoff',
  params: {
    userId:          v.userId,
    sessionId:       v.sessionId,
    fromAgent:       v.fromAgent,
    toAgent:         v.toAgent,
    reason:          v.reason,
    contextSnapshot: v.contextSnapshot
  }
}}];

// Prepara el payload exacto para updateSession en 05_db_manager.
const v = $('🔍 Validar Input de Handoff').first().json;

return [{ json: {
  operation: 'updateSession',
  params: {
    sessionId: v.sessionId,
    agent:     v.toAgent,
    state:     'handoff_received',
    context:   v.contextSnapshot
  }
}}];

// ============================================================
// WARM TRANSFER MESSAGE GENERATOR v1.0.1
// Mensajes de transición personalizados en es / en / pt.
// Variantes aleatorias por par de agentes.
// ============================================================

const validated = $('🔍 Validar Input de Handoff').first().json;
const { fromAgent, toAgent, userLanguage, userName, reason, contextSnapshot } = validated;
const handoffKey = `${fromAgent}_to_${toAgent}`;
const firstName  = userName ? userName.split(' ')[0] : null;
const greeting   = firstName ? ` ${firstName}` : '';

const AGENT_PROFILES = {
  es: {
    NOVA:  { name: 'NOVA',  emoji: '🌟', role: 'orientadora y gestora de citas' },
    SAGE:  { name: 'SAGE',  emoji: '🩺', role: 'especialista en cotizaciones médicas' },
    ATLAS: { name: 'ATLAS', emoji: '🗺️', role: 'consejero de turismo médico' }
  },
  en: {
    NOVA:  { name: 'NOVA',  emoji: '🌟', role: 'scheduling and orientation specialist' },
    SAGE:  { name: 'SAGE',  emoji: '🩺', role: 'medical quote specialist' },
    ATLAS: { name: 'ATLAS', emoji: '🗺️', role: 'medical tourism advisor' }
  },
  pt: {
    NOVA:  { name: 'NOVA',  emoji: '🌟', role: 'orientadora e gestora de consultas' },
    SAGE:  { name: 'SAGE',  emoji: '🩺', role: 'especialista em cotações médicas' },
    ATLAS: { name: 'ATLAS', emoji: '🗺️', role: 'conselheiro de turismo médico' }
  }
};

const lang      = ['es','en','pt'].includes(userLanguage) ? userLanguage : 'es';
const toProfile = AGENT_PROFILES[lang][toAgent];

const MESSAGES = {
  es: {
    NOVA_to_SAGE: [
      `Perfecto${greeting} 👋 Con gusto te conecto con ${toProfile.emoji} *${toProfile.name}*, nuestra ${toProfile.role}.

Vamos a preparar tu solicitud de cotización para que los médicos puedan darte precios precisos. ¿Empezamos?`,
      `Entendido${greeting}. Déjame conectarte con *${toProfile.name}*, quien te acompañará en todo el proceso de cotización ${toProfile.emoji}

No te preocupes, ya le compartí lo que hablamos. ¡En sus manos estás!`
    ],
    NOVA_to_ATLAS: [
      `Claro${greeting} ${toProfile.emoji} Te presento a *${toProfile.name}*, nuestro ${toProfile.role}.

*${toProfile.name}* analizará tus opciones de destino y calculará el costo real del viaje médico. ¿Listo/a para explorar?`
    ],
    SAGE_to_ATLAS: [
      `Excelente${greeting}, tu solicitud está lista ${toProfile.emoji}

Ahora te conecto con *${toProfile.name}*, nuestro ${toProfile.role}. Él analizará las cotizaciones que recibas y te ayudará a elegir el destino ideal considerando el costo total real.

*${toProfile.name}*, aquí contigo 🗺️`,
      `¡Tu expediente está completo${greeting}! Ahora viene la parte emocionante ${toProfile.emoji}

*${toProfile.name}* comparará destinos y calculará cuánto costaría realmente cada opción. ¡Ya tiene todos tus datos!`
    ],
    SAGE_to_NOVA: [
      `Claro${greeting}, te devuelvo con *${toProfile.name}* ${toProfile.emoji}

Ella puede ayudarte con lo que necesites ahora. ¡No has perdido ningún progreso!`
    ],
    ATLAS_to_NOVA: [
      `Por supuesto${greeting} 🌟 Te reconecto con *${toProfile.name}*.

*${toProfile.name}*, aquí contigo de nuevo. ¿En qué más puedes ayudar?`
    ],
    ATLAS_to_SAGE: [
      `Entendido${greeting} ${toProfile.emoji} Te regreso con *${toProfile.name}* para ajustar tu solicitud.

¡Ya tiene todo el contexto!`
    ],
    default: [
      `${toProfile.emoji} Te conecto con *${toProfile.name}*, tu ${toProfile.role}.

Contexto completo ya transferido. ¿En qué puedo ayudarte?`
    ]
  },
  en: {
    NOVA_to_SAGE: [
      `Great${greeting} 👋 Let me connect you with ${toProfile.emoji} *${toProfile.name}*, our ${toProfile.role}.

We'll prepare your quote request so doctors can give you accurate pricing. Shall we begin?`
    ],
    NOVA_to_ATLAS: [
      `Of course${greeting} ${toProfile.emoji} Meet *${toProfile.name}*, our ${toProfile.role}.

Ready to explore your options?`
    ],
    SAGE_to_ATLAS: [
      `Your request is ready${greeting}! ${toProfile.emoji} Connecting you with *${toProfile.name}*, our ${toProfile.role}.

All your data is already with him. Let's find your best destination!`
    ],
    SAGE_to_NOVA: [
      `Sure${greeting}, getting *${toProfile.name}* back for you ${toProfile.emoji} No progress lost!`
    ],
    ATLAS_to_NOVA: [
      `Of course${greeting} 🌟 Reconnecting with *${toProfile.name}*. How else can we help?`
    ],
    ATLAS_to_SAGE: [
      `Got it${greeting} ${toProfile.emoji} Sending you back to *${toProfile.name}*. Context is already there!`
    ],
    default: [
      `${toProfile.emoji} Connecting you with *${toProfile.name}*, your ${toProfile.role}.

Full context already transferred.`
    ]
  },
  pt: {
    NOVA_to_SAGE: [
      `Perfeito${greeting} 👋 Vou te conectar com ${toProfile.emoji} *${toProfile.name}*, nossa ${toProfile.role}. Vamos começar?`
    ],
    SAGE_to_ATLAS: [
      `Seu pedido está pronto${greeting}! ${toProfile.emoji} Conectando com *${toProfile.name}*.

Todos os seus dados já estão com ele. Vamos encontrar seu destino ideal!`
    ],
    SAGE_to_NOVA: [
      `Claro${greeting}, reconectando com *${toProfile.name}* ${toProfile.emoji} Nenhum progresso perdido!`
    ],
    ATLAS_to_NOVA: [
      `Claro${greeting} 🌟 Reconectando com *${toProfile.name}*. Em que mais podemos ajudar?`
    ],
    default: [
      `${toProfile.emoji} Conectando com *${toProfile.name}*, seu ${toProfile.role}.

Contexto completo já transferido!`
    ]
  }
};

const langMsgs  = MESSAGES[lang] || MESSAGES['es'];
const templates = langMsgs[handoffKey] || langMsgs['default'] || MESSAGES['es']['default'];
const idx       = Math.floor(Math.random() * templates.length);

const FIRST_MESSAGES = {
  es: {
    SAGE:  '¿Sobre qué procedimiento médico deseas cotizar? Si ya lo mencionaste, solo confirmo para tener todo claro.',
    ATLAS: '¿Ya tienes cotizaciones de médicos, o aún estás en esa etapa? Cuéntame y vemos el mejor siguiente paso.',
    NOVA:  '¿En qué más puedo ayudarte hoy?'
  },
  en: {
    SAGE:  'What medical procedure would you like quotes for? Just confirm if you already mentioned it.',
    ATLAS: 'Do you already have quotes from doctors, or are you still at that stage?',
    NOVA:  'What else can I help you with today?'
  },
  pt: {
    SAGE:  'Para qual procedimento médico você gostaria de receber orçamentos?',
    ATLAS: 'Você já tem orçamentos de médicos, ou ainda está nessa etapa?',
    NOVA:  'Em que mais posso ajudá-lo hoje?'
  }
};

return [{ json: {
  success:           true,
  handoffKey,
  fromAgent,
  toAgent,
  userId:            validated.userId,
  sessionId:         validated.sessionId,
  userLanguage:      lang,
  handoffMessage:    templates[idx],
  agentFirstMessage: ((FIRST_MESSAGES[lang] || FIRST_MESSAGES['es'])[toAgent]),
  newActiveAgent:    toAgent,
  newSessionState:   'handoff_received',
  _meta: {
    timestamp:      new Date().toISOString(),
    reason,
    dbLogSuccess:   true,
    sessionUpdated: true,
    messageVariant: idx
  }
}}];

// Fallo en log — NO bloqueante. El handoff puede continuar.
const validated = $('🔍 Validar Input de Handoff').first().json;
const dbError   = $input.first().json;

return [{ json: {
  success: false,
  error:   'DB_LOG_FAILED',
  message: 'No se pudo registrar el handoff en la base de datos, pero la operación puede continuar.',
  details: dbError.message || 'Error desconocido en DB',
  fromAgent:  validated.fromAgent,
  toAgent:    validated.toAgent,
  userId:     validated.userId,
  sessionId:  validated.sessionId,
  _meta: { timestamp: new Date().toISOString(), severity: 'warning', blocker: false }
}}];

// Fallo en actualizar sesión — SÍ bloqueante.
// Sin esto el orchestrator no sabrá el agente activo.
const validated = $('🔍 Validar Input de Handoff').first().json;
const dbError   = $input.first().json;

return [{ json: {
  success:  false,
  error:    'SESSION_UPDATE_FAILED',
  message:  'No se pudo actualizar la sesión. El handoff fue cancelado para preservar consistencia.',
  details:  dbError.message || 'Error desconocido en DB',
  fromAgent:  validated.fromAgent,
  toAgent:    validated.toAgent,
  userId:     validated.userId,
  sessionId:  validated.sessionId,
  _meta: { timestamp: new Date().toISOString(), severity: 'error', blocker: true }
}}];

const input = $input.first().json;
return [{ json: {
  success:  false,
  error:    input.errorCode || 'INVALID_INPUT',
  message:  'El input recibido no pasó la validación del Handoff Manager.',
  details:  input.errors || [],
  original: input.original || {},
  _meta: { timestamp: new Date().toISOString(), severity: 'error', blocker: true }
}}];
